/**
 * TanStack Query hooks for User API Keys
 * These are API keys generated by users for programmatic access
 */

import { createMutation, useQueryClient } from '@tanstack/svelte-query';
import { useListPageQuery, type ListPageParams } from '#lib/api/list-page.ts';
import { queryKeys } from '#lib/api/query-client.ts';
import { apiClient } from '#lib/api/client.ts';
import { requireSuccess, unwrapData } from '#lib/api/query-helpers.ts';
import type { components } from '#lib/api/schema';
import { utcTimeZoneSentinel, uuidv4Sentinel } from '#lib/shared/utils/formatting.ts';

export type UserApiKey = components['schemas']['UserApiKey'];
export type UserApiKeyBase = components['schemas']['UserApiKeyBase'];
export type UserOrgPermissions = components['schemas']['UserOrgPermissions'];

/** One page of the signed-in user's API keys. Nothing else lists them, so the page is the only
 * cache: every write refetches it. */
export function useUserApiKeysListQuery(params: () => ListPageParams) {
	return useListPageQuery<UserApiKey>(
		queryKeys.userApiKeys.all,
		({ query, querySerializer }) =>
			apiClient.GET('/api/v1/user-api-keys', { params: { query }, querySerializer }),
		params
	);
}

/**
 * Response type from create user API key endpoint
 */
interface CreateUserApiKeyResponse {
	key: string;
	api_key: UserApiKey;
}

/**
 * Mutation hook for creating a user API key
 * Returns the key string (only shown once) and the created API key
 */
export function useCreateUserApiKeyMutation() {
	const queryClient = useQueryClient();

	return createMutation(() => ({
		mutationFn: async (apiKey: UserApiKey) => {
			const response = unwrapData(
				await apiClient.POST('/api/v1/user-api-keys', { body: apiKey })
			) as CreateUserApiKeyResponse;
			return { keyString: response.key, apiKey: response.api_key };
		},
		onSuccess: () => queryClient.invalidateQueries({ queryKey: queryKeys.userApiKeys.all })
	}));
}

/**
 * Mutation hook for updating a user API key
 */
export function useUpdateUserApiKeyMutation() {
	const queryClient = useQueryClient();

	return createMutation(() => ({
		mutationFn: async (apiKey: UserApiKey) => {
			return unwrapData(
				await apiClient.PUT('/api/v1/user-api-keys/{id}', {
					params: { path: { id: apiKey.id } },
					body: apiKey
				})
			);
		},
		onSuccess: () => queryClient.invalidateQueries({ queryKey: queryKeys.userApiKeys.all })
	}));
}

/**
 * Mutation hook for deleting a user API key
 */
export function useDeleteUserApiKeyMutation() {
	const queryClient = useQueryClient();

	return createMutation(() => ({
		mutationFn: async (id: string) => {
			requireSuccess(
				await apiClient.DELETE('/api/v1/user-api-keys/{id}', {
					params: { path: { id } }
				})
			);
			return id;
		},
		onSuccess: () => queryClient.invalidateQueries({ queryKey: queryKeys.userApiKeys.all })
	}));
}

/**
 * Mutation hook for bulk deleting user API keys
 */
export function useBulkDeleteUserApiKeysMutation() {
	const queryClient = useQueryClient();

	return createMutation(() => ({
		mutationFn: async (ids: string[]) => {
			requireSuccess(await apiClient.POST('/api/v1/user-api-keys/bulk-delete', { body: ids }));
			return ids;
		},
		onSuccess: () => queryClient.invalidateQueries({ queryKey: queryKeys.userApiKeys.all })
	}));
}

/**
 * Mutation hook for rotating a user API key
 */
export function useRotateUserApiKeyMutation() {
	return createMutation(() => ({
		mutationFn: async (keyId: string) => {
			return unwrapData(
				await apiClient.POST('/api/v1/user-api-keys/{id}/rotate', {
					params: { path: { id: keyId } }
				})
			) as string;
		}
	}));
}

/**
 * Create empty form data for a new user API key
 */
export function createEmptyUserApiKeyFormData(): UserApiKey {
	return {
		id: uuidv4Sentinel,
		name: '',
		created_at: utcTimeZoneSentinel,
		updated_at: utcTimeZoneSentinel,
		expires_at: null,
		last_used: null,
		key: '',
		is_enabled: true,
		tags: [],
		user_id: uuidv4Sentinel,
		organization_id: uuidv4Sentinel,
		permissions: 'Viewer',
		site_ids: []
	};
}
